// Construye el contexto que recibe el LLM:
// - daily_text: el mensaje crudo de Slack
// - clients: lista compacta slug → nombre
// - agency_members: 4 personas fijas
// - today: fecha actual ISO
const clientsList = $('Supabase · GET cl_clients').first().json;
const slackEvent = $('Slack · Trigger #dailys').first().json;
const rawText = slackEvent.event?.text || slackEvent.text || '';

// Limpia el prefijo 'daily' al inicio (case insensitive)
const dailyText = rawText.replace(/^\s*daily[:\s-]*/i, '').trim();

const today = new Date();
const todayISO = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;

const clients = (Array.isArray(clientsList) ? clientsList : [])
  .filter(c => c.status !== 'archived')
  .map(c => ({ slug: c.slug, name: c.name }));

return [{
  json: {
    daily_text: dailyText,
    clients,
    agency_members: ['Cristhian Fonseca', 'Cristian Vega', 'Elmer', 'Camilo'],
    today: todayISO,
    slack: {
      ts: slackEvent.event?.ts || slackEvent.ts,
      channel: slackEvent.event?.channel || slackEvent.channel,
      user: slackEvent.event?.user || slackEvent.user,
      thread_ts: slackEvent.event?.thread_ts || slackEvent.event?.ts || slackEvent.ts,
    },
  }
}];

// Mapea las tareas extraídas por OpenAI a payloads de cl_items.
// - Resuelve client_slug → client_id usando la lista de clientes.
// - Aplica fallbacks razonables y marca source='slack'.
// - Si client_slug no existe, log y descartar (NO crear con id inválido).

const openAiOutput = $('OpenAI · Extraer tareas').first().json;
const ctx = $('Build context (clientes + daily)').first().json;
const clientsList = $('Supabase · GET cl_clients').first().json;

// El nodo OpenAI con jsonOutput devuelve { message: { content: '...' } } o un parsed directamente
let parsed;
try {
  const raw = openAiOutput.message?.content || openAiOutput.content || openAiOutput;
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return [{ json: { error: 'No se pudo parsear el JSON de OpenAI', raw: openAiOutput, valid: [], invalid: [] } }];
}

const tasks = Array.isArray(parsed?.tasks) ? parsed.tasks : [];
const slugToId = Object.fromEntries((clientsList || []).map(c => [c.slug, c.id]));
const validMembers = new Set(ctx.agency_members);

const valid = [];
const invalid = [];

tasks.forEach((t, i) => {
  const slug = t.client_slug || null;
  const ownerType = slug ? 'client' : 'agency';

  if (slug && !slugToId[slug]) {
    invalid.push({ reason: `client_slug '${slug}' no existe`, task: t });
    return;
  }
  if (!t.title || !t.title.trim()) {
    invalid.push({ reason: 'sin título', task: t });
    return;
  }

  valid.push({
    owner_type: ownerType,
    client_id: slug ? slugToId[slug] : null,
    title: String(t.title).trim().substring(0, 200),
    description: (t.description || '').trim() || null,
    assigned_to: (t.assigned_to && validMembers.has(t.assigned_to)) ? t.assigned_to : null,
    priority: ['urgent','high','medium','low'].includes(t.priority) ? t.priority : 'medium',
    block: t.block || null,
    due_date: t.due_date || null,
    status: 'pending',
    source: 'slack',
    slack_message_ts: ctx.slack.ts,
    slack_channel_id: ctx.slack.channel,
    slack_user_id: ctx.slack.user,
    updated_by: 'agency',
    position: (i + 1) * 10,
  });
});

return [{ json: { valid, invalid, slack: ctx.slack } }];

// Construye el mensaje de respuesta para Slack agrupando por cliente.
const valid = $('Build payloads cl_items').first().json.valid || [];
const invalid = $('Build payloads cl_items').first().json.invalid || [];
const slack = $('Build payloads cl_items').first().json.slack;
const inserted = $('Supabase · INSERT cl_items').first().json || [];

const clientsList = $('Supabase · GET cl_clients').first().json || [];
const idToName = Object.fromEntries(clientsList.map(c => [c.id, c.name]));

// Agrupar por destino
const byTarget = {};
valid.forEach(t => {
  const key = t.client_id ? idToName[t.client_id] || 'Cliente' : 'Agencia';
  byTarget[key] = (byTarget[key] || 0) + 1;
});

const lines = Object.entries(byTarget).map(([k, n]) => `• *${n}* en _${k}_`);
let text = `✅ Creé ${valid.length} tarea${valid.length===1?'':'s'} desde tu daily:\n${lines.join('\n')}`;
if (invalid.length > 0) {
  text += `\n\n⚠ ${invalid.length} omitida${invalid.length===1?'':'s'} (slug no encontrado o sin título)`;
}

return [{
  json: {
    text,
    channel: slack.channel,
    thread_ts: slack.thread_ts,
  }
}];
